struct Part {
    PCWSTR name;
    bool (*enabled)();
    // tool side: runs in the one windhawk.exe helper process
    BOOL (*toolInit)();
    void (*toolUninit)();
    void (*toolSettings)();
    void (*toolFp)(Fp&);
    bool toolRunning;  // ToolInit ran and said yes
    std::wstring fp;   // its settings when it last looked
    // shell side: runs in the programs in appInclude (null for the tray tools)
    const wchar_t* const* appInclude;
    BOOL (*appInit)();
    void (*appBefore)();
    void (*appUninit)();
    void (*appSettings)();
    bool appRunning;
    bool appEnabledAtInit;
};

